"""Rover example: the DFMEA lines of the other functions, so every function of the tree has its line (nothing left for
« Compléter le DFMEA »). Upper-level functions take the worst failure of their branch; constraints and esteem functions are
« Rien à signaler », justified in Failure Effect, as the course allows when the team says why."""
from .diamond import _d

RAS = "RAS"


def _ras(focus, function, why):
    return {"higher": "Rover et son utilisateur", "focus": focus, "lower": "—", "function": function, "failure_mode": RAS, "effect": why}


